THRESHOLD = 0.8   # the maker's default of 0.5 stops too early

def enough(question, passages):
    state = "QUESTION:\n%s\n\nPASSAGES:\n%s" % (
        question, "\n\n".join("- %s" % p for p in passages))
    qs = {"enough": {"type": "noul",
          "instructions": "Are these passages enough to answer the question, or should we keep looking?"}}
    return decide(state, qs)["enough"]["noul"]

passages = []
while len(passages) < 40:
    passages += search_next(question)
    if enough(question, passages) >= THRESHOLD:
        break
answer(question, passages)

def worth_starting(last_report, changes):
    state = "LAST RUN ENDED WITH:\n%s\n\nWHAT CHANGED SINCE:\n%s" % (
        last_report, "\n".join("- %s" % c for c in changes))
    qs = {"run": {"type": "noul",
          "instructions": "Is there anything for this scheduled run to do right now?"}}
    return decide(state, qs)["run"]["noul"]

if worth_starting(last_report, changes) < 0.4:
    log("nothing to do, skipped before starting")
    return
run_the_expensive_pipeline()   # only now does the clock matter
